const JarvisModule=(()=>{const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const J={open:false,tab:'voice',messages:[],conversation:null,draft:'',status:'Ready',busy:false,voice:false,muted:false,language:'en-GB',key:''};
let context=()=>({}),ask,selectLesson,recognition,voiceEpoch=0;
function configureJarvis(getContext,onAsk,onLesson){context=getContext;ask=onAsk;selectLesson=onLesson;const c=context();const key=c.profileKey+':'+c.lessonId;if(key!==J.key){stopVoice();J.key=key;J.messages=[];J.conversation=null;J.draft='';J.status='Ready';J.busy=false;}}
function jarvisHTML(){const c=context(),ready=c.enabled&&c.lessonId;return `<button type="button" class="jarvis-launcher" data-jarvis="toggle" aria-label="Open Jarvis assistant" aria-expanded="${J.open}"><span class="jarvis-mini-orb"></span><span>Jarvis</span></button><aside id="jarvis-panel" class="jarvis-panel ${J.open?'is-open':''}" aria-label="Jarvis learning assistant"${J.open?'':' hidden'}><header class="jarvis-head"><div><strong>✦ Jarvis</strong><small>Your learning companion · ${escape(c.studentName||'Family')}</small></div><button type="button" data-jarvis="close" aria-label="Close Jarvis">×</button></header><div class="jarvis-tabs" role="tablist"><button type="button" role="tab" aria-selected="${J.tab==='chat'}" data-jarvis-tab="chat">Chat</button><button type="button" role="tab" aria-selected="${J.tab==='voice'}" data-jarvis-tab="voice">Voice</button></div><label class="jarvis-lesson">Study portion<select data-jarvis-lesson><option value="">Choose a portion</option>${(c.lessons||[]).map(l=>`<option value="${escape(l.id)}"${l.id===c.lessonId?' selected':''}>${escape(l.subject+' · '+l.lesson_name)}</option>`).join('')}</select></label>${J.tab==='voice'?`<div class="jarvis-voice"><div class="eyebrow">JARVIS · VOICE</div><div class="jarvis-orb ${J.status==='Listening'?'listening':J.status==='Speaking'?'speaking':''}" aria-hidden="true"><span>〰</span></div><h2 aria-live="polite">${escape(J.status)}</h2><p>${!c.enabled?'Tutor connection pending':!c.lessonId?'Choose a lesson above':'One question at a time. I’m here to help.'}</p><div class="jarvis-voice-buttons"><button type="button" data-jarvis="listen" class="btn secondary small"${!ready||J.busy||J.muted?' disabled':''} aria-label="Start listening">🎙 Speak</button><button type="button" data-jarvis="mute" class="btn secondary small" aria-pressed="${J.muted}">${J.muted?'Unmute':'Mute'}</button><button type="button" data-jarvis="end" class="btn small end-call">End</button></div><label class="jarvis-language">Speaking language<select data-jarvis-language>${[['en-GB','English'],['ar-AE','Arabic'],['fr-FR','French'],['hi-IN','Hindi']].map(([v,l])=>`<option value="${v}"${v===J.language?' selected':''}>${l}</option>`).join('')}</select></label><small class="muted">Tap Speak to allow the microphone. Speech uses your browser’s service; availability varies by device.</small></div>`:''}<div class="jarvis-transcript" aria-live="polite">${J.messages.length?J.messages.map(m=>`<div><strong>${m.role==='user'?'You':'Jarvis'}</strong><p>${escape(m.text)}</p></div>`).join(''):`<div><strong>Jarvis</strong><p>Hi, I’m Jarvis. Choose a school portion and ask me to explain it, give you a hint, or help with practice.</p></div>`}</div><form id="jarvis-form"><label class="sr-only" for="jarvis-question">Ask Jarvis</label><div class="row"><input id="jarvis-question" name="question" placeholder="Ask Jarvis…" maxlength="3000" value="${escape(J.draft)}" required${!ready||J.busy?' disabled':''}><button type="submit" class="btn small"${!ready||J.busy?' disabled':''}>${J.busy?'…':'Send'}</button></div></form></aside>`;}
function refresh(){const old=document.querySelector('#jarvis-panel'),launch=document.querySelector('.jarvis-launcher');if(!old||!launch)return;const holder=document.createElement('div');holder.innerHTML=jarvisHTML();launch.replaceWith(holder.firstElementChild);old.replaceWith(holder.firstElementChild);const transcript=document.querySelector('.jarvis-transcript');if(transcript)transcript.scrollTop=transcript.scrollHeight;}
function stopVoice(){voiceEpoch++;J.voice=false;try{recognition?.abort();}catch{}recognition=null;if(typeof window!=='undefined')window.speechSynthesis?.cancel();J.status='Ready';}
async function submit(message){const c=context();if(J.busy||!message.trim()||!c.enabled||!c.lessonId)return;const key=J.key;J.busy=true;J.status='Thinking';J.draft=message;refresh();try{const response=await ask(message,J.conversation);if(key!==J.key)return;J.messages.push({role:'user',text:message},{role:'assistant',text:response.text});J.conversation=response.conversation_id;J.draft='';J.status='Ready';if(J.voice&&!J.muted&&window.speechSynthesis){const utterance=new SpeechSynthesisUtterance(response.text);utterance.lang=J.language;utterance.onstart=()=>{J.status='Speaking';refresh();};utterance.onend=()=>{J.status='Ready';refresh();};window.speechSynthesis.speak(utterance);}}catch(e){if(key===J.key){J.status='Could not respond';J.messages.push({role:'assistant',text:e.message});}}finally{if(key===J.key){J.busy=false;refresh();}}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-jarvis],[data-jarvis-tab]');if(!button)return;if(button.dataset.jarvisTab){J.tab=button.dataset.jarvisTab;stopVoice();refresh();return;}const action=button.dataset.jarvis;if(action==='toggle'){J.open=!J.open;if(!J.open)stopVoice();}if(action==='close'){J.open=false;stopVoice();}if(action==='end')stopVoice();if(action==='mute'){J.muted=!J.muted;if(J.muted){voiceEpoch++;try{recognition?.abort();}catch{}window.speechSynthesis?.cancel();J.status='Muted';}else J.status='Ready';}if(action==='listen'){
  if(!context().enabled||!context().lessonId||J.muted)return;
  const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!Recognition){J.status='Use the Chat tab';J.messages.push({role:'assistant',text:'Voice input is not supported in this browser. You can type your question below.'});refresh();return;}
  stopVoice();J.voice=true;const epoch=voiceEpoch;recognition=new Recognition();recognition.lang=J.language;recognition.continuous=false;recognition.interimResults=false;
  recognition.onstart=()=>{J.status='Listening';refresh();};recognition.onresult=e=>{if(epoch!==voiceEpoch||!J.voice)return;const words=e.results[0][0].transcript;submit(words);};
  recognition.onerror=e=>{if(epoch!==voiceEpoch)return;J.status=e.error==='not-allowed'?'Microphone not allowed':'Try Chat instead';refresh();};
  recognition.onend=()=>{if(epoch===voiceEpoch&&!J.busy&&J.status==='Listening'){J.status='Ready';refresh();}};
  try{recognition.start();}catch{J.status='Use the Chat tab';}
}refresh();});
document.addEventListener('change',event=>{if(event.target.matches('[data-jarvis-lesson]')){stopVoice();selectLesson(event.target.value);}if(event.target.matches('[data-jarvis-language]')){stopVoice();J.language=event.target.value;refresh();}});
document.addEventListener('input',event=>{if(event.target.id==='jarvis-question')J.draft=event.target.value;});
document.addEventListener('submit',event=>{if(event.target.id!=='jarvis-form')return;event.preventDefault();submit(new FormData(event.target).get('question')||'');});
if(typeof window!=='undefined')window.addEventListener('pagehide',stopVoice);


return {configureJarvis,jarvisHTML,stopJarvisVoice:stopVoice};})();
